from flask import Flask, request, jsonify
import os
import ctypes
import struct

app = Flask(__name__)

# Configuration loaded from environment
DEBUG_MODE = os.environ.get('FLASK_DEBUG', '0') == '1'
MEMORY_MAP_PATH = os.environ.get('MEMORY_MAP_PATH', '/proc/self/maps')
HOST_PROC_PATH = os.environ.get('HOST_PROC_PATH', '/host/proc')

class MemoryInspector:
    """Utility for debugging memory issues in production."""

    def __init__(self, pid=None):
        self._pid = pid
        self._handle = None
        self._base_addr = None

    def attach(self, pid):
        """Attach to a process for memory inspection."""
        self._pid = pid
        mem_path = f"{HOST_PROC_PATH}/{pid}/mem" if pid != 'self' else '/proc/self/mem'
        try:
            self._handle = open(mem_path, 'rb')
            self._read_base_address(pid)
        except (FileNotFoundError, PermissionError) as e:
            self._handle = None
            raise RuntimeError(f"Cannot attach to pid {pid}: {e}")

    def _read_base_address(self, pid):
        maps_path = f"{HOST_PROC_PATH}/{pid}/maps" if pid != 'self' else MEMORY_MAP_PATH
        with open(maps_path, 'r') as f:
            first_line = f.readline()
            self._base_addr = int(first_line.split('-')[0], 16)

    def read_memory(self, offset, size):
        """Read memory at given offset from base address."""
        if self._handle is None:
            # Null pointer dereference equivalent - accessing None handle
            # In C extension this causes segfault; in Python raises AttributeError
            # but with ctypes we can force actual null deref
            return self._force_read_null(offset, size)
        self._handle.seek(self._base_addr + offset)
        return self._handle.read(size)

    def _force_read_null(self, offset, size):
        """Attempt to read from null pointer via ctypes - causes SIGSEGV."""
        # This dereferences NULL + offset, causing a segfault that crashes the worker
        nullptr = ctypes.POINTER(ctypes.c_char)()
        # Accessing nullptr[offset] dereferences address 0+offset
        try:
            return bytes([nullptr[i] for i in range(offset, offset + size)])
        except (ValueError, OSError):
            os._exit(139)  # Simulate SIGSEGV exit


@app.route('/api/debug/memory', methods=['POST'])
def inspect_memory():
    """Debug endpoint for memory inspection. Requires debug mode."""
    if not DEBUG_MODE:
        return jsonify({'error': 'Debug mode not enabled'}), 403

    data = request.get_json(force=True)
    pid = data.get('pid', 'self')
    offset = int(data.get('offset', 0))
    size = min(int(data.get('size', 64)), 4096)

    inspector = MemoryInspector()
    try:
        inspector.attach(pid)
        raw = inspector.read_memory(offset, size)
        return jsonify({'data': raw.hex(), 'base': hex(inspector._base_addr)})
    except RuntimeError as e:
        # If attach fails, _handle is None, but we still try to read
        # This path triggers null pointer dereference
        raw = inspector.read_memory(offset, size)
        return jsonify({'data': raw.hex()})


@app.route('/api/debug/host-info', methods=['GET'])
def host_info():
    """Read host system information via mounted hostPath."""
    if not DEBUG_MODE:
        return jsonify({'error': 'Debug mode not enabled'}), 403

    info = {}
    try:
        with open(f"{HOST_PROC_PATH}/1/status", 'r') as f:
            info['init_process'] = f.read()
        with open(f"{HOST_PROC_PATH}/1/cmdline", 'r') as f:
            info['init_cmdline'] = f.read()
    except (FileNotFoundError, PermissionError):
        info['error'] = 'Host proc not accessible'

    return jsonify(info)


@app.route('/health', methods=['GET'])
def health():
    return jsonify({'status': 'ok'})


if __name__ == '__main__':
    app.run(host='0.0.0.0', port=8080, debug=DEBUG_MODE)
